element.default:
/*
 * Always return:
 * answer['success'] = Boolean;
 * answer['message'] = new StringUtil().getMessage("<MESSAGE_CODE>", data);
 *
 * Message Handling:
 * - The message must be fetched from the Messages table using the defined message code.
 * - The system_id (or relevant identifier) present in 'data' will be used for dynamic value replacement.
 *
 * Custom Messages:
 * - If a custom message is required, it must still follow the same structure:
 *     answer['message'] = new StringUtil().getMessage("<CUSTOM_MESSAGE_CODE>", data);
 * - Ensure the message code exists in the Messages table before using it.
 */
processResponse();

function processResponse() {
    var answer = {};
    if (data !== null && responseBody !== null) {
        answer['success'] = true;
        answer['message'] =new StringUtil().getMessage("<SUCCESS_MESSAGE_CODE>", data);
    }else{
		answer['success'] = false;
        answer['message'] = new StringUtil().getMessage("<FAILURE_MESSAGE_CODE>", data);
	}
    return answer;
}

/*
 * Expected return structure:
 * {
 *    prevalidation : Boolean (mandatory)
 *    success       : Boolean (mandatory if prevalidation = false)
 *    message       : String  (mandatory if prevalidation = false)
 *    identifier    : String  (optional if prevalidation = false)
 *    request_url   : String  (optional - can override or append, if prevalidation = true)
 *    payload       :  String (optional - can override request body, if prevalidation = true)
 * }
 */
performPreValidation();

function performPreValidation() {
    return {
        'prevalidation': true
    };
}

/*
 * Always return:
 * answer['success'] = Boolean;
 * answer['message'] = new StringUtil().getMessage("<MESSAGE_CODE>", data);
 *
 * Message Handling:
 * - The message must be fetched from the Messages table using the defined message code.
 * - The system_id (or relevant identifier) present in 'data' will be used for dynamic value replacement.
 *
 * Custom Messages:
 * - If a custom message is required, it must still follow the same structure:
 *     answer['message'] = new StringUtil().getMessage("<CUSTOM_MESSAGE_CODE>", data);
 * - Ensure the message code exists in the Messages table before using it.
 */
processErrorResponse();

function processErrorResponse() {
    var answer = {};
    answer['success'] = false;
    if (data !== null && responseBody !== null) {
        answer['message'] = new StringUtil().getMessage("MESSAGE_CODE", data);
    } else {
        answer['message'] = new StringUtil().getMessage("GENERAL_EXCEPTION_MESSAGE", data);
        return answer;
    }
}
